class StringTable_Movable {
public:
  StringTable_Movable() = default;
  // No user-declared dtor, copy, or move ops.
  // Compiler generates all five special members.
  // This class is both copyable and movable.
private:
  std::map<int, std::string> values;
};

class StringTable_CopyOnly {
public:
  StringTable_CopyOnly() { /* ... */ }

  // User-declared destructor
  ~StringTable_CopyOnly() { /* ... logging ... */ }

  // Dtor suppresses generation of move operations!
  // The class is now copyable, but NOT movable.
private:
  std::map<int, std::string> values;
};
